changeSet.sql:
CREATE TABLE pkg_outbox_message (
    id           uuid          NOT NULL CONSTRAINT pk_pkg_outbox_message PRIMARY KEY,
    type         varchar(200)  NOT NULL,
    payload      jsonb         NOT NULL,
    occurred_at  timestamptz   NOT NULL,
    processed_at timestamptz,
    attempts     integer       NOT NULL DEFAULT 0,
    error        varchar(2000)
);

CREATE INDEX ix_pkg_outbox_message_unprocessed ON pkg_outbox_message (occurred_at) WHERE processed_at IS NULL;
